// Catechism Quest: saved state, progress, spaced repetition and cloud sync.
// Loaded as a classic script by index.html; files share top-level names and must load in the order listed there.
'use strict';
// ================= STATE =================
// The catechism texts come from catechisms.js (generated by tools/build_data.py).
// Families can also add their own quests (S.custom); those stay on this device only.
const BUILT=window.CATECHISMS||{};
const CAT=Object.assign({},BUILT);
let QUEST_KEYS=[];
function landsFor(n){const out=[];for(let i=0;i<n;i+=4)out.push({name:LAND_NAMES[(i/4)%LAND_NAMES.length],qs:[...Array(Math.min(4,n-i)).keys()].map(j=>i+j+1)});return out;}
function syncCustom(){
 Object.keys(CAT).forEach(id=>{if(!BUILT[id])delete CAT[id];});
 S.custom.forEach(c=>{CAT[c.id]={id:c.id,title:c.title,short:c.title.length>18?c.title.slice(0,17)+'…':c.title,custom:true,qas:c.qas,lands:landsFor(c.qas.length)};});
 QUEST_KEYS=['wsc','hc'].filter(x=>CAT[x]).concat(S.custom.map(c=>c.id));
}
const KEY='catechism-quest-app-v1';
function newKid(name,hero){return{id:uid(),name:name||'Hero',hero:hero||null,quest:null,open:{},colors:{},owned:{},prog:{},cps:{},srs:{},mast:{},guard:{},coins:0,swords:1,songs:[0],song:0,made:Date.now(),at:Date.now()};}
const clone=x=>JSON.parse(JSON.stringify(x));
function load(){try{const s=localStorage.getItem(KEY);if(s)return JSON.parse(s);}catch(e){}return null;}
let S=load()||{v:1,kids:[],kidId:null,sound:true,music:true,dels:[],custom:[]};
function fix(){
 if(!Array.isArray(S.kids))S.kids=[];
 if(!Array.isArray(S.custom))S.custom=[];
 S.custom=S.custom.filter(c=>c&&typeof c.id==='string'&&/^my_[a-z0-9]+$/.test(c.id)&&Array.isArray(c.qas));
 S.custom.forEach(c=>{
  c.title=String(c.title||'').trim()||'My Quest';
  c.qas=c.qas.filter(x=>x&&typeof x.q==='string'&&typeof x.a==='string'&&x.q.trim()&&x.a.trim()).map((x,i)=>({n:i+1,q:x.q,a:x.a}));
 });
 S.custom=S.custom.filter(c=>c.qas.length);
 syncCustom();
 S.kids.forEach(k=>{
  if(!k.id)k.id=uid();if(!k.name)k.name='Hero';
  if(k.hero&&!HEROES[k.hero])k.hero='knight';
  // a quest someone made on another device isn't here; keep the pointer, the app asks for a quest
  if(k.quest&&!CAT[k.quest]&&!/^my_/.test(k.quest))k.quest=null;
  ['colors','owned','prog','cps','open','srs','mast','guard'].forEach(f=>{if(!k[f]||typeof k[f]!=='object'||Array.isArray(k[f]))k[f]={};});
  if(typeof k.coins!=='number')k.coins=0;if(typeof k.swords!=='number')k.swords=1;
  if(!Array.isArray(k.songs))k.songs=[0];if(!k.songs.includes(0))k.songs.unshift(0);
  if(typeof k.song!=='number'||!k.songs.includes(k.song))k.song=0;
  if(typeof k.made!=='number')k.made=0;if(typeof k.at!=='number')k.at=0;
  // spaced repetition: every learned question gets a review schedule. Lambs learned before this
  // existed get one now, spread over the next few days so they don't all wander off at once.
  let j=0;const t0=today();
  Object.keys(k.prog).forEach(key=>{if(k.prog[key]>0&&!(k.srs[key]&&typeof k.srs[key].d==='number')){k.srs[key]={b:k.prog[key]>=3?1:0,d:t0+1+(j++%6)};}});
  Object.keys(k.srs).forEach(key=>{if(!(k.prog[key]>0))delete k.srs[key];});
 });
 S.kids.sort((a,b)=>a.made-b.made);
 if(!S.kids.some(k=>k.id===S.kidId))S.kidId=S.kids[0]?S.kids[0].id:null;
 if(typeof S.sound!=='boolean')S.sound=true;if(typeof S.music!=='boolean')S.music=true;
 if(!Array.isArray(S.dels))S.dels=[];
}
fix();
const kid=()=>S.kids.find(k=>k.id===S.kidId)||null;
const QD=()=>{const k=kid();return(k&&CAT[k.quest])||null;};   // the current kid's catechism
const QAS=()=>{const q=QD();return q?q.qas:[];};
const N=()=>QAS().length;
// Progress keys: "wsc:12" for question 12, "wsc:L3" for the castle ending land 3.
const pkey=(qid,i)=>qid+':'+(i+1);
const ckey=(qid,s)=>qid+':L'+(s+1);
const stars=(k,i,qid)=>k.prog[pkey(qid||k.quest,i)]||0;
const learnedIn=(k,qid)=>{const c=CAT[qid];return c?c.qas.filter((x,i)=>stars(k,i,qid)>0).length:0;};
// ----- spaced repetition (the flock) -----
// Each learned question is a lamb. Review gaps grow 1, 3, 7, 14, 30… days after each right answer;
// when a review is due the lamb wanders off until the kid finds it again in a quick review.
const GAPS=[1,3,7,14,30,60,120,240];
function today(){const d=new Date();return Math.floor((d.getTime()-d.getTimezoneOffset()*60000)/86400000);}
const srsOf=(k,i,qid)=>k.srs[pkey(qid||k.quest,i)];
const isLost=(k,i,qid)=>{const r=srsOf(k,i,qid);return stars(k,i,qid)>0&&!!r&&r.d<=today();};
const learnedIdx=k=>QAS().map((x,i)=>i).filter(i=>stars(k,i)>0);
const lostIdx=k=>learnedIdx(k).filter(i=>isLost(k,i)).sort((a,b)=>srsOf(k,a).d-srsOf(k,b).d||a-b);
function srsSeed(k,i){k.srs[pkey(k.quest,i)]={b:0,d:today()+1};}
// right: the next review moves further out. wrong: start over, back again tomorrow.
function srsReview(k,i,ok){const key=pkey(k.quest,i),r=k.srs[key]||{b:0,d:0};
 r.b=ok?Math.min(GAPS.length-1,r.b+1):0;r.d=today()+GAPS[ok?r.b:0];k.srs[key]=r;return r;}
const daysText=n=>n<=0?'today':n===1?'tomorrow':`in ${n} days`;
const sheepCount=k=>k.quest?learnedIdx(k).length-lostIdx(k).length:0;
const inGame=n=>['study','fill','bonus','herd','build','guard'].includes(n);

// ----- saving -----
// This device keeps everything in localStorage. When the page runs inside Claude with the
// db capability, each kid is also saved as their own document ("kid_<id>"), so two devices
// playing different kids never overwrite each other. Which kid is playing, sound and music stay per device.
let COL=null,UNSUB=null,READY=false,CLOUD=false,flushing=false,saveT=null;
const DIRTY=new Set();
function persist(){try{localStorage.setItem(KEY,JSON.stringify(S));}catch(e){}}
function save(k){
 if(k&&k.id){k.at=Date.now();DIRTY.add(k.id);}
 persist();
 if(DIRTY.size||S.dels.length){clearTimeout(saveT);saveT=setTimeout(flush,900);}
}
function goLocal(){COL=null;CLOUD=false;READY=false;if(UNSUB){try{UNSUB();}catch(e){}}UNSUB=null;safeRender();}
async function flush(){
 if(!COL||!READY||flushing)return;flushing=true;
 try{
  while(COL&&(DIRTY.size||S.dels.length)){
   let job,back;
   if(S.dels.length){const id=S.dels[0];job=COL.doc('kid_'+id).delete().then(()=>{S.dels=S.dels.filter(x=>x!==id);persist();});back=()=>{};}
   else{
    const id=[...DIRTY][0];DIRTY.delete(id);back=()=>DIRTY.add(id);
    const k=S.kids.find(x=>x.id===id);if(!k)continue;
    const b=clone(k);delete b.synced;job=COL.doc('kid_'+id).set(b).then(()=>{k.synced=true;persist();});
   }
   try{await job;if(!CLOUD){CLOUD=true;if(V.name==='settings')render();}}
   catch(e){
    const c=e&&e.code;back();
    if(c==='invalid_argument'||c==='revoked'){goLocal();break;} // e.g. a link viewer who can't save to the cloud
    clearTimeout(saveT);saveT=setTimeout(flush,c==='quota_exceeded'?60000:5000);break;
   }
  }
 }finally{flushing=false;}
}
function applySnap(snap){
 const rk={};snap.docs.forEach(d=>{if(d.exists&&d.id.startsWith('kid_'))rk[d.id.slice(4)]=d.data();});
 const final=!snap.metadata.fromCache;let changed=false;
 Object.keys(rk).forEach(id=>{
  if(S.dels.includes(id))return;const r=rk[id],l=S.kids.find(x=>x.id===id);
  if(!l){S.kids.push(Object.assign(clone(r),{synced:true}));changed=true;}
  else if(!DIRTY.has(id)&&(r.at||0)>(l.at||0)){Object.assign(l,clone(r),{synced:true});changed=true;}
  else{l.synced=true;if(final&&(l.at||0)>(r.at||0))DIRTY.add(id);}
 });
 if(final){
  S.kids=S.kids.filter(k=>{
   if(rk[k.id]||DIRTY.has(k.id))return true;
   if(k.synced&&!(inGame(V.name)&&k.id===S.kidId)){changed=true;return false;} // removed on another device
   DIRTY.add(k.id);return true;
  });
  if(Object.keys(rk).length)CLOUD=true;
  if(!READY){READY=true;changed=true;}
 }
 if(changed){fix();persist();safeRender();}
 if(DIRTY.size||S.dels.length)flush();
}
async function initCloud(){
 try{
  if(!window.claude||!window.claude.use)return;
  const [db,user]=await Promise.all([window.claude.use('db'),window.claude.use('user')]);
  if(!db||!user)return;
  const id=await user.id();if(!id)return;
  COL=db.collection('data/users/'+id);
  UNSUB=COL.onSnapshot(s=>{try{applySnap(s);}catch(e){}},e=>{UNSUB=null;const c=e&&e.code;if(c==='invalid_argument'||c==='revoked')goLocal();});
 }catch(e){}
}
function safeRender(){if(['title','players','quests','map','flock','shop','music','settings'].includes(V.name))render();}
